from pathlib import Path


def replace_once(path: str, old: str, new: str) -> None:
    p = Path(path)
    text = p.read_text(encoding='utf-8')
    count = text.count(old)
    if count != 1:
        raise SystemExit(f'{path}: guard expected one match, found {count}: {old[:120]!r}')
    p.write_text(text.replace(old, new), encoding='utf-8')

# Wire a post-coordinator observer into the production ingress adapter. Default is a no-op.
controller = 'mmo-bootstrap/src/main/java/com/branz/mmorpg/bootstrap/CombatSessionController.java'
replace_once(
    controller,
    '    private final Map<UUID, LiveSession> sessions = new HashMap<>();\n',
    '    private final Map<UUID, LiveSession> sessions = new HashMap<>();\n'
    '    private BiConsumer<Player, InputRouteOutcome> primaryRouteObserver = (player, outcome) -> {};\n',
)
replace_once(
    controller,
    '    private boolean routePrimaryAttack(Player player, LiveSession session) {\n',
    '    void setPrimaryRouteObserver(BiConsumer<Player, InputRouteOutcome> observer) {\n'
    '        primaryRouteObserver = Objects.requireNonNull(observer, "observer");\n'
    '    }\n\n'
    '    private boolean routePrimaryAttack(Player player, LiveSession session) {\n',
)
replace_once(
    controller,
    '        routed.ifPresent(outcome -> handleRoute(player, session, outcome));\n',
    '        routed.ifPresent(\n'
    '                outcome -> {\n'
    '                    handleRoute(player, session, outcome);\n'
    '                    primaryRouteObserver.accept(player, outcome);\n'
    '                });\n',
)

# Add a JVM-property-only server-side orchestrator. It provisions through durable production APIs.
probe = Path('mmo-bootstrap/src/main/java/com/branz/mmorpg/bootstrap/PhysicalClientIngressAcceptanceProbe.java')
if probe.exists():
    raise SystemExit(f'{probe}: already exists')
probe.write_text('''package com.branz.mmorpg.bootstrap;\n\nimport com.branz.mmorpg.api.identity.DefinitionId;\nimport com.branz.mmorpg.api.identity.ItemId;\nimport com.branz.mmorpg.api.result.Result;\nimport com.branz.mmorpg.combat.input.InputRouteOutcome;\nimport com.branz.mmorpg.items.definition.ItemDefinition;\nimport com.branz.mmorpg.items.definition.ItemEngine;\nimport com.branz.mmorpg.items.equipment.EquipmentLoadout;\nimport com.branz.mmorpg.items.equipment.EquipmentSlot;\nimport java.io.IOException;\nimport java.nio.charset.StandardCharsets;\nimport java.nio.file.Files;\nimport java.nio.file.Path;\nimport java.util.Objects;\nimport java.util.Optional;\nimport java.util.UUID;\nimport org.bukkit.entity.Player;\nimport org.bukkit.plugin.java.JavaPlugin;\n\n/** Test-only real-client acceptance for physical LMB -> Paper ingress -> primary coordinator. */\nfinal class PhysicalClientIngressAcceptanceProbe {\n    static final String ENABLE_PROPERTY = "mmo.bootstrap.physical-lmb-acceptance-test";\n    static final String MARKER_PROPERTY = "mmo.bootstrap.physical-lmb-acceptance-marker";\n    static final String PASS_MARKER = "PHYSICAL_LMB_INGRESS_ACCEPTANCE_PASS";\n    private static final DefinitionId TRAINING_BLADE = DefinitionId.of("weapon.training_blade");\n\n    private final JavaPlugin plugin;\n    private final CharacterSessionController characters;\n    private final ItemDefinition trainingBlade;\n    private final String contentVersion;\n    private UUID armedPlayer;\n    private boolean completed;\n\n    private PhysicalClientIngressAcceptanceProbe(\n            JavaPlugin plugin,\n            CharacterSessionController characters,\n            ItemEngine items,\n            String contentVersion) {\n        this.plugin = Objects.requireNonNull(plugin, "plugin");\n        this.characters = Objects.requireNonNull(characters, "characters");\n        this.trainingBlade =\n                Objects.requireNonNull(items, "items")\n                        .find(TRAINING_BLADE)\n                        .orElseThrow(() -> new IllegalStateException("training blade definition missing"));\n        this.contentVersion = Objects.requireNonNull(contentVersion, "contentVersion");\n    }\n\n    static void install(\n            JavaPlugin plugin,\n            CharacterSessionController characters,\n            CombatSessionController combat,\n            ItemEngine items,\n            String contentVersion) {\n        if (!Boolean.getBoolean(ENABLE_PROPERTY)) {\n            return;\n        }\n        PhysicalClientIngressAcceptanceProbe probe =\n                new PhysicalClientIngressAcceptanceProbe(plugin, characters, items, contentVersion);\n        characters.addReadyHandler(probe::onCharacterReady);\n        combat.setPrimaryRouteObserver(probe::onPrimaryRouted);\n        plugin.getServer().getScheduler().runTaskLater(plugin, probe::timeout, 20L * 45L);\n        plugin.getLogger().info("PHYSICAL_LMB_INGRESS_ACCEPTANCE_ARMED");\n    }\n\n    private void onCharacterReady(Player player) {\n        if (completed || armedPlayer != null) {\n            return;\n        }\n        player.getInventory().setHeldItemSlot(0);\n        Optional<ItemId> existing = findTrainingBlade(player);\n        if (existing.isPresent()) {\n            equip(player, existing.orElseThrow());\n            return;\n        }\n        characters.grantTestValue(\n                player,\n                trainingBlade,\n                contentVersion,\n                result -> {\n                    if (result instanceof Result.Failure<LoadedCharacterSession, CharacterSessionErrorCode> failure) {\n                        fail("grant failed: " + failure.error().code() + " " + failure.detail());\n                        return;\n                    }\n                    ItemId granted =\n                            findTrainingBlade(player)\n                                    .orElseThrow(\n                                            () ->\n                                                    new IllegalStateException(\n                                                            "granted training blade was not projected"));\n                    equip(player, granted);\n                });\n    }\n\n    private Optional<ItemId> findTrainingBlade(Player player) {\n        return characters.active(player).flatMap(\n                session ->\n                        session.snapshot().itemRecords().stream()\n                                .filter(record -> record.definitionId().equals(TRAINING_BLADE))\n                                .map(record -> record.itemId())\n                                .findFirst());\n    }\n\n    private void equip(Player player, ItemId itemId) {\n        LoadedCharacterSession active =\n                characters\n                        .active(player)\n                        .orElseThrow(() -> new IllegalStateException("character session disappeared"));\n        EquipmentLoadout desired =\n                active.snapshot().equipment().with(EquipmentSlot.MAIN_HAND, Optional.of(itemId));\n        characters.commitEquipment(\n                player,\n                desired,\n                contentVersion,\n                result -> {\n                    if (result instanceof Result.Failure<LoadedCharacterSession, CharacterSessionErrorCode> failure) {\n                        fail("equip failed: " + failure.error().code() + " " + failure.detail());\n                        return;\n                    }\n                    player.getInventory().setHeldItemSlot(0);\n                    armedPlayer = player.getUniqueId();\n                    plugin.getLogger().info("PHYSICAL_LMB_INGRESS_ACCEPTANCE_PLAYER_READY");\n                });\n    }\n\n    private void onPrimaryRouted(Player player, InputRouteOutcome outcome) {\n        if (completed || armedPlayer == null || !armedPlayer.equals(player.getUniqueId())) {\n            return;\n        }\n        completed = true;\n        try {\n            writeMarker();\n            plugin.getLogger().info(PASS_MARKER + " outcome=" + outcome);\n        } catch (IOException exception) {\n            fail("marker write failed: " + exception.getMessage());\n            return;\n        }\n        plugin.getServer().getScheduler().runTaskLater(plugin, plugin.getServer()::shutdown, 2L);\n    }\n\n    private void timeout() {\n        if (!completed) {\n            fail("timed out before a physical LMB reached PrimaryAttackInputCoordinator");\n        }\n    }\n\n    private void fail(String detail) {\n        if (completed) {\n            return;\n        }\n        completed = true;\n        plugin.getLogger().severe("PHYSICAL_LMB_INGRESS_ACCEPTANCE_FAIL " + detail);\n        plugin.getServer().getScheduler().runTask(plugin, plugin.getServer()::shutdown);\n    }\n\n    private static void writeMarker() throws IOException {\n        String raw = System.getProperty(MARKER_PROPERTY, "").trim();\n        if (raw.isEmpty()) {\n            throw new IllegalStateException("physical LMB acceptance marker path is missing");\n        }\n        Path marker = Path.of(raw).toAbsolutePath().normalize();\n        Path parent = marker.getParent();\n        if (parent != null) {\n            Files.createDirectories(parent);\n        }\n        Files.writeString(marker, PASS_MARKER + System.lineSeparator(), StandardCharsets.UTF_8);\n    }\n}\n''', encoding='utf-8')

# Wire probe after production runtime controllers and handlers exist.
plugin = 'mmo-bootstrap/src/main/java/com/branz/mmorpg/bootstrap/BranzMmoPlugin.java'
needle = '        resourcePackGate.setReadyHandler(characterSessionController::onPackReady);\n'
replacement = needle + '''        PhysicalClientIngressAcceptanceProbe.install(\n                this,\n                characterSessionController,\n                combatSessionController,\n                activeItemEngine.get(),\n                snapshot.manifest().contentVersion());\n'''
replace_once(plugin, needle, replacement)

# Add a dedicated runServer acceptance mode with fail-closed marker verification.
build = 'mmo-bootstrap/build.gradle.kts'
needle = '    val combatAcceptance = providers.gradleProperty("combatAcceptance").orNull == "true"\n'
replacement = needle + '    val physicalLmbAcceptance = providers.gradleProperty("physicalLmbAcceptance").orNull == "true"\n'
replace_once(build, needle, replacement)
needle = '    if (combatAcceptance) {\n'
replacement = '''    if (physicalLmbAcceptance) {\n        val acceptanceMarker =\n            project.layout.buildDirectory.file("physical-lmb-ingress-acceptance.pass").get().asFile\n        jvmArgs(\n            "-Dmmo.bootstrap.physical-lmb-acceptance-test=true",\n            "-Dmmo.bootstrap.physical-lmb-acceptance-marker=${acceptanceMarker.absolutePath}",\n        )\n        doFirst {\n            acceptanceMarker.delete()\n        }\n        doLast {\n            check(\n                acceptanceMarker.isFile &&\n                    acceptanceMarker.readText().trim() == "PHYSICAL_LMB_INGRESS_ACCEPTANCE_PASS",\n            ) {\n                "Physical LMB ingress acceptance marker was not produced."\n            }\n        }\n    } else if (combatAcceptance) {\n'''
replace_once(build, needle, replacement)

# Standalone Fabric 26.2 client gametest project. It is intentionally not included by root settings.gradle.kts.
root = Path('acceptance/minecraft-client-26.2')
if root.exists():
    raise SystemExit(f'{root}: already exists')
(root / 'src/clientGametest/java/com/branz/mmorpg/acceptance').mkdir(parents=True)
(root / 'src/clientGametest/resources').mkdir(parents=True)
(root / 'settings.gradle').write_text('''pluginManagement {\n    repositories {\n        maven { url = 'https://maven.fabricmc.net/' }\n        gradlePluginPortal()\n        mavenCentral()\n    }\n}\nrootProject.name = 'branz-physical-lmb-acceptance'\n''', encoding='utf-8')
(root / 'gradle.properties').write_text('''org.gradle.jvmargs=-Xmx2G\norg.gradle.daemon=false\nminecraft_version=26.2\nloader_version=0.19.3\nloom_version=1.17-SNAPSHOT\nfabric_api_version=0.156.0+26.2\n''', encoding='utf-8')
(root / 'build.gradle').write_text('''plugins {\n    id 'net.fabricmc.fabric-loom' version "${loom_version}"\n}\n\nrepositories {\n    mavenCentral()\n}\n\ndependencies {\n    minecraft "com.mojang:minecraft:${project.minecraft_version}"\n    implementation "net.fabricmc:fabric-loader:${project.loader_version}"\n    implementation "net.fabricmc.fabric-api:fabric-api:${project.fabric_api_version}"\n}\n\nfabricApi.configureTests {\n    createSourceSet = true\n    modId = 'branz-physical-lmb-acceptance'\n}\n\ntasks.withType(JavaCompile).configureEach {\n    options.release = 25\n}\n\njava {\n    sourceCompatibility = JavaVersion.VERSION_25\n    targetCompatibility = JavaVersion.VERSION_25\n}\n''', encoding='utf-8')
(root / 'src/clientGametest/resources/fabric.mod.json').write_text('''{\n  "schemaVersion": 1,\n  "id": "branz-physical-lmb-acceptance",\n  "version": "1.0.0",\n  "name": "Branz Physical LMB Acceptance",\n  "environment": "client",\n  "entrypoints": {\n    "fabric-client-gametest": [\n      "com.branz.mmorpg.acceptance.PhysicalLmbClientGameTest"\n    ]\n  },\n  "depends": {\n    "fabricloader": ">=0.19.3",\n    "minecraft": "26.2",\n    "fabric-api": "*"\n  }\n}\n''', encoding='utf-8')
(root / 'src/clientGametest/java/com/branz/mmorpg/acceptance/PhysicalLmbClientGameTest.java').write_text('''package com.branz.mmorpg.acceptance;\n\nimport net.fabricmc.fabric.api.client.gametest.v1.FabricClientGameTest;\nimport net.fabricmc.fabric.api.client.gametest.v1.context.ClientGameTestContext;\nimport net.minecraft.client.gui.screens.ConnectScreen;\nimport net.minecraft.client.multiplayer.ServerData;\nimport net.minecraft.client.multiplayer.resolver.ServerAddress;\n\npublic final class PhysicalLmbClientGameTest implements FabricClientGameTest {\n    @Override\n    public void runTest(ClientGameTestContext context) {\n        String address = System.getProperty("branz.acceptance.server", "localhost:25565");\n        context.runOnClient(\n                client -> {\n                    ServerData server = new ServerData("Branz acceptance", address, ServerData.Type.OTHER);\n                    ConnectScreen.startConnecting(\n                            client.gui.screen(),\n                            client,\n                            ServerAddress.parseString(address),\n                            server,\n                            false,\n                            null);\n                });\n        context.waitFor(client -> client.level != null && client.player != null, 20 * 20);\n        context.waitTicks(80);\n        context.getInput().pressMouse(0);\n        context.waitTicks(80);\n        context.getInput().pressMouse(0);\n        context.waitTicks(40);\n    }\n}\n''', encoding='utf-8')
